<template>
	<view class="">
		<view class="shopTitle_box">
			<view class="" :style="{height:cellphone+'rpx'}">

			</view>
			<view class="shopTitle d-flex a-center" @click="routerTo('/pagesA/map/map')">
				<span class="f-size-24 color-3d mr-10">{{vuex_shop_info.title || ''}} </span>
				<view class="pt-4">
					<u-icon name="arrow-down-fill" color="#3d3d3d" size="12"></u-icon>
				</view>
			</view>
		</view>


		<view class="p-re">
			<u-swiper @click="swiperclick($event,1)" keyName='image' :list="swiperList1" height='510rpx'
				imgMode='aspectFill'></u-swiper>

			<view class="head d-flex a-center j-sb">
				<view class="color-f f-size-26">
					欢迎来到{{vuex_common.share_title || ''}}
				</view>

				<view class="color-f f-size-26 d-flex a-center" @click="routerGo('/pagesB/vipCode/vipCode')">
					<span class="mr-10">会员码</span>
					<image style="width: 34rpx;" src="../../static/index/idx6.png" mode="widthFix"></image>
				</view>
			</view>
		</view>



		<view class="box_1">
			<view class="box_card_box mb-30">
				<view class="box_card_box_1 d-flex a-center j-sb" @click="routerGo('/pagesA/recharge/recharge')">
					<view class="color-03 f-size-32 f-bold">
						充值购卡
					</view>
					<view class="">
						<image class="img_2" src="../../static/index/idx1.png" mode="widthFix"></image>
					</view>
				</view>
				<view class="box_card_box_1 d-flex a-center j-sb" @click="routerGo('/pagesE/carNumber/carNumber')">
					<view class="color-03 f-size-32 f-bold">
						绑定车辆
					</view>
					<view class="">
						<image class="img_1" src="../../static/index/idx2.png" mode="widthFix"></image>
					</view>
				</view>
				<view class="box_card_box_1 d-flex a-center j-sb" @click="routerGo('/pages/shop/shop')">
					<view class="color-03 f-size-32 f-bold">
						商城下单
					</view>
					<view class="">
						<image class="img_1" src="../../static/index/idx3.png" mode="widthFix"></image>
					</view>
				</view>
				<view class="box_card_box_1 d-flex a-center j-sb" @click="routerGo('/pagesE/integral/integral')">
					<view class="color-03 f-size-32 f-bold">
						积分商城
					</view>
					<view class="">
						<image class="img_1" src="../../static/index/idx4.png" mode="widthFix"></image>
					</view>
				</view>
			</view>
			<view class="mb-26">
				<u-swiper @click="swiperclick($event,2)" keyName='image' :list="swiperList2" height='120rpx'
					imgMode='aspectFill'></u-swiper>
			</view>


			<u-swiper @click="swiperclick($event,3)" keyName='image' :list="swiperList3" height='212rpx'
				imgMode='aspectFill'></u-swiper>

			<view class="shop_box mt-42">
				<view class="shop_box_title d-flex a-center j-sb">
					<view class="f-size-28 f-blod color-3d">
						附近网点
					</view>
					<view class=" d-flex a-center" @click="routerGo('/pagesA/map/map')">
						<span class="f-size-24 color-03">全部网点</span>
						<view class="pt-6">
							<u-icon name="arrow-right" color="#0F553E" size="14"></u-icon>
						</view>
					</view>
				</view>

				<empty v-if="list.length==0"></empty>
				<view class="shop_box_item d-flex a-center j-sb" @click="setshopInfo(item)" v-for="(item,index) in list"
					:key="index">
					<image class="shop_box_item_img" :src="item.image" mode="aspectFill"></image>
					<view class="shop_box_item_left flex-column d-flex j-sb">
						<view class="">
							<view class="f-size-32 color-3d f-bold beyond j-sb ">
								<view class="sp_title">
									{{item.title || ''}}
								</view>
								<view class="color-9 f-size-24 me-text-beyond">
									{{item.distance || ''}}
								</view>
							</view>
							<view class="color-9 f-size-24 mt-10 me-text-beyond">
								位置:{{item.address}}
							</view>
						</view>

						<view class="color-9 f-size-24">
							营业时间:{{item.start_times}}-{{item.end_times}}
						</view>
					</view>
				</view>
			</view>
		</view>
	</view>
</template>

<script>
	export default {
		data() {
			return {
				shopShow: true,
				swiperList1: [],
				swiperList2: [],
				swiperList3: [],
				couponidxList: [],
				list: [],
				page: 1
			}
		},
		onLoad(e) {
			if (e.pid) {
				uni.setStorageSync('pid', e.pid)
			}
			if (e.scene) {
				uni.setStorageSync('pid', e.scene)
			}
			if (this.vuex_token) {
				this.$store.commit('userApi')
			}
			this.$store.commit('cellphone')
			this.indexbannerApi(1)
			this.indexbannerApi(2)
			this.indexbannerApi(3)

			this.storeListApi()

			if (!uni.getStorageSync('storeid')) {
				this.$store.dispatch('defaultShop')
			}

		},
		onReachBottom() {
			this.page++
			this.storeListApi(1)
		},
		methods: {
			// 切换店铺
			setshopInfo(item) {
				if (item.is_business == 1) {
					this.$store.state.vuex_shop_info = item
					this.$store.commit('caremptyApi')
					uni.reLaunch({
						url: '/pages/shop/shop'
					})
				} else {
					this.showToast('该店铺已歇业,请选择其他店铺')
				}

			},
			// 店铺列表
			async storeListApi(e) {
				let res = await this.storeList({
					page: this.page
				})
				if (res.code == 1) {
					if (e == 1) {
						this.list = [...this.list, ...res.data.rows]
					} else {
						this.list = res.data.rows
					}
				}
			},

			async indexbannerApi(e) {
				let res = await this.indexbanner({
					type: e
				})
				if (res.code == 1) {
					this[`swiperList${e}`] = res.data
				}
			},

			swiperclick(e, type) {
				let url = this[`swiperList${type}`][e].url
				if (url == '/pages/index/index' || url == '/pages/shop/shop' || url == '/pages/order/order' || url ==
					'/pages/my/my') {
					uni.reLaunch({
						url
					})
				} else {
					uni.navigateTo({
						url
					})
				}

			},

		}
	}
</script>

<style lang="scss">
	page {
		background: #fafafa;
		padding: 0 0 20rpx;
	}

	.box_1 {
		background: #fafafa;
		position: relative;
		z-index: 99;
		padding: 30rpx;
		box-sizing: border-box;

		.box_card_box {
			display: grid;
			grid-template-columns: repeat(2, 334rpx);
			row-gap: 20rpx;
			justify-content: space-between;

			.box_card_box_1 {

				width: 334rpx;
				height: 160rpx;
				background: url('../../static/index/idx5.png') no-repeat;
				background-size: 100% 100%;
				padding: 0rpx 10rpx 0 20rpx;
				box-sizing: border-box;

				.img_1 {
					width: 156rpx;
				}

				.img_2 {
					width: 100rpx;
				}
			}
		}
	}

	.shop_box_item {
		width: 690rpx;
		height: 202rpx;
		background: #FFFFFF;
		border-radius: 14rpx 14rpx 14rpx 14rpx;
		margin-top: 26rpx;

		.shop_box_item_img {
			width: 230rpx;
			height: 202rpx;
			border-radius: 14rpx 0rpx 0rpx 14rpx;

		}

		.shop_box_item_left {
			width: calc(100% - 250rpx);
			height: 202rpx;
			padding: 16rpx 0;
			box-sizing: border-box;

			.sp_title {
				width: 350rpx;
			}
		}
	}

	.head {
		position: absolute;
		bottom: 0;
		left: 50%;
		transform: translateX(-50%);
		width: 690rpx;
		height: 66rpx;
		background: #303136;
		border-radius: 20rpx 20rpx 0rpx 0rpx;
		padding: 16rpx 30rpx;
		box-sizing: border-box;
	}

	.shopTitle_box {
		position: absolute;
		top: 1vh;
		left: 36rpx;
		z-index: 99990;
	}

	.shopTitle {
		padding: 15rpx 30rpx;
		box-sizing: border-box;
		background-color: #fafafa;
		border-radius: 30rpx;

	}
</style>